import os, time
from cffi import FFI

ffi = FFI()
ffi.cdef("""
typedef struct evp_cipher_ctx_st EVP_CIPHER_CTX;
typedef struct evp_cipher_st EVP_CIPHER;
EVP_CIPHER_CTX *EVP_CIPHER_CTX_new(void);
void EVP_CIPHER_CTX_free(EVP_CIPHER_CTX *ctx);
const EVP_CIPHER *EVP_aes_128_gcm(void);
const EVP_CIPHER *EVP_aes_192_gcm(void);
const EVP_CIPHER *EVP_aes_256_gcm(void);
int EVP_EncryptInit_ex(EVP_CIPHER_CTX *ctx, const EVP_CIPHER *type,
                       void *impl, const unsigned char *key, const unsigned char *iv);
int EVP_EncryptUpdate(EVP_CIPHER_CTX *ctx, unsigned char *out, int *outl,
                      const unsigned char *in, int inl);
int EVP_EncryptFinal_ex(EVP_CIPHER_CTX *ctx, unsigned char *out, int *outl);
int EVP_CIPHER_CTX_ctrl(EVP_CIPHER_CTX *ctx, int type, int arg, void *ptr);
""")
lib = ffi.dlopen("/usr/local/lib/libcrypto.dylib")

EVP_CTRL_GCM_SET_IVLEN = 0x9
EVP_CTRL_GCM_GET_TAG = 0x10

CIPHERS = {16: lib.EVP_aes_128_gcm(), 24: lib.EVP_aes_192_gcm(), 32: lib.EVP_aes_256_gcm()}

def encrypt(key, nonce, plaintext, aad):
    ctx = lib.EVP_CIPHER_CTX_new()
    try:
        if lib.EVP_EncryptInit_ex(ctx, CIPHERS[len(key)], ffi.NULL, ffi.NULL, ffi.NULL) != 1:
            raise RuntimeError("init1")
        if lib.EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, len(nonce), ffi.NULL) != 1:
            raise RuntimeError("ivlen")
        if lib.EVP_EncryptInit_ex(ctx, ffi.NULL, ffi.NULL, key, nonce) != 1:
            raise RuntimeError("init2")
        outlen = ffi.new("int *")
        if aad:
            if lib.EVP_EncryptUpdate(ctx, ffi.NULL, outlen, aad, len(aad)) != 1:
                raise RuntimeError("aad")
        ct = ffi.new("unsigned char[]", len(plaintext) + 16)
        if lib.EVP_EncryptUpdate(ctx, ct, outlen, plaintext, len(plaintext)) != 1:
            raise RuntimeError("update")
        total = outlen[0]
        if lib.EVP_EncryptFinal_ex(ctx, ct + total, outlen) != 1:
            raise RuntimeError("final")
        total += outlen[0]
        tag = ffi.new("unsigned char[]", 16)
        if lib.EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1:
            raise RuntimeError("tag")
        return ffi.buffer(ct, total)[:], ffi.buffer(tag, 16)[:]
    finally:
        lib.EVP_CIPHER_CTX_free(ctx)

from cryptography.hazmat.primitives.ciphers.aead import AESGCM
key = os.urandom(16)
nonce = os.urandom(12)
pt = os.urandom(60_000 * 1024)
aad = os.urandom(32)

ref = AESGCM(key).encrypt(nonce, pt, aad)
ct, tag = encrypt(key, nonce, pt, aad)
print("match", ct == ref[:-16], tag == ref[-16:])

t0 = time.perf_counter()
for _ in range(3):
    encrypt(key, nonce, pt, aad)
print("cffi:", (time.perf_counter()-t0)/3)

t0 = time.perf_counter()
for _ in range(3):
    AESGCM(key).encrypt(nonce, pt, aad)
print("cryptography:", (time.perf_counter()-t0)/3)
EOF"}

{"command":"cat > aesgcm_fast.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>

static const EVP_CIPHER *ciphers[33] = {0};

static int init_ciphers(void) {
    if (ciphers[16]) return 0;
    ciphers[16] = EVP_aes_128_gcm();
    ciphers[24] = EVP_aes_192_gcm();
    ciphers[32] = EVP_aes_256_gcm();
    return 0;
}

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    int has_aad = 0;
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)) {
        /* try without aad: reset */
        PyErr_Clear();
        if (!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &pt))
            return NULL;
        has_aad = 0;
    } else {
        has_aad = 1;
    }
    init_ciphers();
    if (key.len != 16 && key.len != 24 && key.len != 32) {
        PyErr_SetString(PyExc_ValueError, "bad key size");
        goto err_release;
    }
    const EVP_CIPHER *cipher = ciphers[key.len];

    PyObject *ct = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tag = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct || !tag) { Py_XDECREF(ct); Py_XDECREF(tag); goto err_release; }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) { Py_DECREF(ct); Py_DECREF(tag); PyErr_SetString(PyExc_RuntimeError, "ctx"); goto err_release; }

    int ok = 1;
    int outlen = 0;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)nonce.len, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf) != 1) ok = 0;
    if (ok && has_aad && aad.len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad.buf, (int)aad.len) != 1) ok = 0;
    }
    if (ok && pt.len > 0) {
        if (EVP_EncryptUpdate(ctx, (unsigned char *)PyBytes_AS_STRING(ct), &outlen,
                              pt.buf, (int)pt.len) != 1) ok = 0;
    }
    int final_len = 0;
    if (ok && EVP_EncryptFinal_ex(ctx, (unsigned char *)PyBytes_AS_STRING(ct) + outlen, &final_len) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, PyBytes_AS_STRING(tag)) != 1) ok = 0;
    EVP_CIPHER_CTX_free(ctx);

    if (!ok) {
        Py_DECREF(ct); Py_DECREF(tag);
        PyErr_SetString(PyExc_RuntimeError, "encrypt failed");
        goto err_release;
    }
    PyBuffer_Release(&key);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&pt);
    if (has_aad) PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ct, tag);

err_release:
    PyBuffer_Release(&key);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&pt);
    if (has_aad) PyBuffer_Release(&aad);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef module = {PyModuleDef_HEAD_INIT, "aesgcm_fast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_aesgcm_fast(void) { return PyModule_Create(&module); }
EOF
export TMPDIR="$PWD/tmp"
cc -O3 -shared -fPIC -I/usr/local/include -I/Library/Frameworks/Python.framework/Versions/3.11/include/python3.11 \
   -o aesgcm_fast.so aesgcm_fast.c -L/usr/local/lib -lcrypto -undefined dynamic_lookup 2>&1
echo EXIT:$?
ls -la aesgcm_fast.so"}

