#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec/1e9;
}

int main() {
    size_t n = 60000UL * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n + 64);
    unsigned char key[16], nonce[12], aad[32], tag[16];
    FILE *f = fopen("/dev/urandom", "rb");
    fread(pt, 1, n, f); fread(key, 1, 16, f); fread(nonce, 1, 12, f); fread(aad, 1, 32, f);
    fclose(f);

    for (int i = 0; i < 8; i++) {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        int outlen = 0;
        double t0 = now();
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
        int fl = 0;
        EVP_EncryptFinal_ex(ctx, ct + outlen, &fl);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        double t1 = now();
        EVP_CIPHER_CTX_free(ctx);
        printf("iter %d: %.4f s  (%.2f GB/s)\n", i, t1-t0, n/(t1-t0)/1e9);
    }
    /* memcpy baseline */
    for (int i = 0; i < 3; i++) {
        double t0 = now();
        memcpy(ct, pt, n);
        double t1 = now();
        printf("memcpy %d: %.4f s (%.2f GB/s throughput, %.2f GB/s bus)\n", i, t1-t0, n/(t1-t0)/1e9, 2*n/(t1-t0)/1e9);
    }
    /* touch baseline */
    volatile unsigned long sink = 0;
    for (int i = 0; i < 3; i++) {
        double t0 = now();
        unsigned long s = 0;
        for (size_t j = 0; j < n; j += 64) s += pt[j];
        sink = s;
        double t1 = now();
        printf("read %d: %.4f s (%.2f GB/s) sink=%lu\n", i, t1-t0, n/(t1-t0)/1e9, sink);
    }
    return 0;
}
EOF
export TMPDIR="$PWD/tmp"
cc -O3 -I/usr/local/include -o bench_gcm bench_gcm.c -L/usr/local/lib -lcrypto 2>&1 && ./bench_gcm"}

