#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#define N (60000UL*1024)
static double now(void){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec/1e9;}
static unsigned char *src, *dst;
typedef struct {size_t start,end;} range_t;
static void *worker(void *arg){
    range_t *r = arg;
    memcpy(dst+r->start, src+r->start, r->end-r->start);
    return NULL;
}
int main(){
    src = aligned_alloc(64, N); dst = aligned_alloc(64, N);
    memset(src, 1, N);
    for (int threads = 1; threads <= 6; threads++) {
        pthread_t th[16]; range_t rs[16];
        size_t chunk = N/threads;
        double t0 = now();
        for (int rep = 0; rep < 3; rep++) {
            for (int i=0;i<threads;i++){rs[i].start=i*chunk; rs[i].end=(i==threads-1)?N:(i+1)*chunk; pthread_create(&th[i],NULL,worker,&rs[i]);}
            for (int i=0;i<threads;i++) pthread_join(th[i],NULL);
        }
        double dt = (now()-t0)/3;
        printf("threads %d: %.4f s  throughput %.2f GB/s  bus %.2f GB/s\n", threads, dt, N/dt/1e9, 2*N/dt/1e9);
    }
    return 0;
}
EOF
