{"command":"cat > bench_par.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/aes.h>
#include <openssl/evp.h>

void aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                       const void *key, const unsigned char ivec[16], unsigned char *Xi);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
void gcm_ghash_clmul(unsigned char *Xi, const void *Htable, const unsigned char *inp, size_t len);

static double now(void){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec/1e9;}

#define N (60000UL*1024)
#define BLOCK 16
#define MAXTH 8

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    AES_KEY *key;
    unsigned char ivec[16];
    unsigned char Xi[16];
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    memset(j->Xi, 0, 16);
    aesni_gcm_encrypt(j->in, j->out, j->len, j->key, j->ivec, j->Xi);
    return NULL;
}

static void inc_ctr(unsigned char ctr[16], size_t blocks) {
    /* increment last 32 bits (GCM standard counter) by `blocks` */
    unsigned int c = ((unsigned int)ctr[12]<<24)|((unsigned int)ctr[13]<<16)|((unsigned int)ctr[14]<<8)|ctr[15];
    c += (unsigned int)blocks;
    ctr[12] = c>>24; ctr[13] = c>>16; ctr[14] = c>>8; ctr[15] = c;
}

int main() {
    unsigned char *pt = aligned_alloc(64, N);
    unsigned char *ct = aligned_alloc(64, N);
    memset(pt, 0x5a, N);
    unsigned char key[16], nonce[12];
    memset(key, 1, 16); memset(nonce, 2, 12);

    AES_KEY aeskey;
    aesni_set_encrypt_key(key, 128, &aeskey);

    /* reference EVP output */
    unsigned char *ref = aligned_alloc(64, N);
    unsigned char tag[16];
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen=0, fl=0;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, ref, &outlen, pt, (int)N);
    EVP_EncryptFinal_ex(ctx, ref+outlen, &fl);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);

    for (int threads = 1; threads <= 6; threads++) {
        size_t blocks = N / BLOCK;
