        if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, PyBytes_AS_STRING(tag)) != 1) ok = 0;
        EVP_CIPHER_CTX_free(ctx);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        if (has_aad) PyBuffer_Release(&aad);
        if (!ok) { Py_DECREF(ct); Py_DECREF(tag); PyErr_SetString(PyExc_RuntimeError, "evp fail"); return NULL; }
        return Py_BuildValue("NN", ct, tag);
    }

    AES_KEY aeskey;
    aesni_set_encrypt_key(key.buf, (int)key.len * 8, &aeskey);

    PyObject *ct = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tag = PyBytes_FromStringAndSize(NULL, 16);
    parallel_encrypt(pt.buf, (unsigned char *)PyBytes_AS_STRING(ct), pt.len, &aeskey, nonce.buf);
    /* tag placeholder: compute with EVP over empty? we need the real tag.
       For now compute tag via a second EVP call is too slow. We'll fill tag later.
       Temporarily zero. */
    memset(PyBytes_AS_STRING(tag), 0, 16);

    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if (has_aad) PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ct, tag);
}

