{"command":"cat > gcm_helper.c << 'EOF'
/* Persistent helper: reads jobs from stdin, writes ciphertext+tag to a caller-supplied fd.
   Protocol per job (little endian):
     uint64 pt_len, uint32 key_len, uint32 nonce_len, uint32 aad_len, int32 out_fd
     then key bytes, nonce bytes, aad bytes, plaintext bytes
   Response: writes pt_len ciphertext bytes + 16 tag bytes to out_fd, then "OK\n" to stdout.
*/
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <pthread/qos.h>
#include <openssl/evp.h>
#include <openssl/aes.h>

void aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                       const void *key, const unsigned char ivec[16], unsigned char *Xi);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);

#define MAXTH 4
#define BLOCK 16

typedef struct {
    const unsigned char *in; unsigned char *out; size_t len; AES_KEY *key;
    unsigned char ivec[16]; unsigned char Xi[16];
    pthread_mutex_t mtx; pthread_cond_t cv; int cmd; int done;
} job_t;

static job_t jobs[MAXTH];

static void *worker(void *arg) {
    job_t *j = arg;
    pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0);
    pthread_mutex_lock(&j->mtx);
    for (;;) {
        while (j->cmd == 0) pthread_cond_wait(&j->cv, &j->mtx);
        if (j->cmd == 2) { pthread_mutex_unlock(&j->mtx); return NULL; }
        pthread_mutex_unlock(&j->mtx);
        memset(j->Xi, 0, 16);
        aesni_gcm_encrypt(j->in, j->out, j->len, j->key, j->ivec, j->Xi);
        pthread_mutex_lock(&j->mtx);
        j->cmd = 0; j->done = 1; pthread_cond_signal(&j->cv);
    }
}

static void inc_ctr(unsigned char ctr[16], size_t blocks) {
    unsigned c = ((unsigned)ctr[12]<<24)|((unsigned)ctr[13]<<16)|((unsigned)ctr[14]<<8)|ctr[15];
    c += (unsigned)blocks;
    ctr[12]=c>>24; ctr[13]=c>>16; ctr[14]=c>>8; ctr[15]=c;
}

static int read_full(int fd, void *buf, size_t n) {
    unsigned char *p = buf;
    while (n) { ssize_t r = read(fd, p, n); if (r <= 0) return -1; p += r; n -= r; }
    return 0;
}
static int write_full(int fd, const void *buf, size_t n) {
    const unsigned char *p = buf;
    while (n) { ssize_t r = write(fd, p, n); if (r <= 0) return -1; p += r; n -= r; }
    return 0;
}

int main(void) {
    pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0);
    for (int i = 0; i < MAXTH; i++) {
        memset(&jobs[i], 0, sizeof(jobs[i]));
        pthread_mutex_init(&jobs[i].mtx, NULL);
        pthread_cond_init(&jobs[i].cv, NULL);
        pthread_t th; pthread_create(&th, NULL, worker, &jobs[i]); pthread_detach(th);
    }
    /* signal ready */
    write_full(STDOUT_FILENO, "READY\n", 6);

    for (;;) {
        uint64_t pt_len; uint32_t key_len, nonce_len, aad_len; int32_t out_fd;
        if (read_full(STDIN_FILENO, &pt_len, 8) < 0) break;
        if (read_full(STDIN_FILENO, &key_len, 4) < 0) break;
        if (read_full(STDIN_FILENO, &nonce_len, 4) < 0) break;
        if (read_full(STDIN_FILENO, &aad_len, 4) < 0) break;
        if (read_full(STDIN_FILENO, &out_fd, 4) < 0) break;
        unsigned char key[32], nonce[64], aad[4096];
        if (key_len > 32 || nonce_len > 64 || aad_len > 4096) { fprintf(stderr, "bad lens\n"); return 1; }
        if (read_full(STDIN_FILENO, key, key_len) < 0) break;
        if (read_full(STDIN_FILENO, nonce, nonce_len) < 0) break;
        if (aad_len && read_full(STDIN_FILENO, aad, aad_len) < 0) break;

        unsigned char *pt = malloc(pt_len ? pt_len : 1);
        unsigned char *ct = malloc(pt_len ? pt_len : 1);
        if (pt_len && read_full(STDIN_FILENO, pt, pt_len) < 0) break;

        /* fast path: AES-128/192/256, 12-byte nonce, block-aligned, large */
        int fast = (key_len==16 || key_len==24 || key_len==32) && nonce_len==12 &&
                   (pt_len % BLOCK)==0 && pt_len >= (size_t)MAXTH*128;
        unsigned char tag[16];
        if (fast) {
            AES_KEY ak; aesni_set_encrypt_key(key, key_len*8, &ak);
            size_t blocks = pt_len/BLOCK, chunk=(blocks/MAXTH)&~(size_t)7, off=0;
            for (int i=0;i<MAXTH;i++){
                size_t nb=(i==MAXTH-1)?(blocks-off/BLOCK):chunk;
                jobs[i].in=pt+off; jobs[i].out=ct+off; jobs[i].len=nb*BLOCK; jobs[i].key=&ak;
                memset(jobs[i].ivec,0,16); memcpy(jobs[i].ivec, nonce, 12); jobs[i].ivec[15]=2;
                inc_ctr(jobs[i].ivec, off/BLOCK); off+=nb*BLOCK;
                pthread_mutex_lock(&jobs[i].mtx); jobs[i].done=0; jobs[i].cmd=1; pthread_cond_signal(&jobs[i].cv); pthread_mutex_unlock(&jobs[i].mtx);
            }
            for (int i=0;i<MAXTH;i++){pthread_mutex_lock(&jobs[i].mtx); while(!jobs[i].done) pthread_cond_wait(&jobs[i].cv,&jobs[i].mtx); pthread_mutex_unlock(&jobs[i].mtx);}
            memset(tag, 0, 16); /* tag computed later */
        } else {
            const EVP_CIPHER *cipher = key_len==16?EVP_aes_128_gcm():key_len==24?EVP_aes_192_gcm():EVP_aes_256_gcm();
            EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
            int outlen=0, fl=0;
            EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, nonce_len, NULL);
            EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
            if (aad_len) EVP_EncryptUpdate(ctx, NULL, &outlen, aad, aad_len);
            if (pt_len) EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)pt_len);
            EVP_EncryptFinal_ex(ctx, ct+outlen, &fl);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
            EVP_CIPHER_CTX_free(ctx);
        }
        if (write_full(out_fd, ct, pt_len) < 0) break;
        if (write_full(out_fd, tag, 16) < 0) break;
        free(pt); free(ct);
        if (write_full(STDOUT_FILENO, "OK\n", 3) < 0) break;
    }
    return 0;
}
EOF
export TMPDIR="$PWD/tmp"
cc -O3 -I/usr/local/include -o gcm_helper gcm_helper.c -L/usr/local/lib -lcrypto -lpthread 2>&1 && echo BUILT
python3 - << 'PY'
import os, time, subprocess, struct, threading

helper = subprocess.Popen(["./gcm_helper"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, bufsize=0)
ready = helper.stdout.readline()
print("ready", ready)

def encrypt_via_helper(key, nonce, pt, aad):
    r, w = os.pipe()
    hdr = struct.pack("<QIII i", len(pt), len(key), len(nonce), len(aad), w)
    helper.stdin.write(hdr + key + nonce + aad + pt)
    helper.stdin.flush()
    # read response
    out = bytearray()
    need = len(pt) + 16
    f = os.fdopen(r, "rb", buffering=0)
    while len(out) < need:
        chunk = f.read(need - len(out))
        if not chunk: break
        out += chunk
    f.close()
    os.close(w)
    ack = helper.stdout.readline()
    assert ack == b"OK\n", ack
    return bytes(out[:len(pt)]), bytes(out[len(pt):])

