{"command":"cat > aesgcm_fast.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/aes.h>
#include <pthread.h>
#include <pthread/qos.h>
#include <time.h>
#include <string.h>
#include <stdatomic.h>
#include <stdio.h>

void aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                       const void *key, const unsigned char ivec[16], unsigned char *Xi);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);

#define MAXTH 4
#define BLOCK 16

typedef struct {
    const unsigned char *in; unsigned char *out; size_t len; AES_KEY *key;
    unsigned char ivec[16]; unsigned char Xi[16];
    atomic_int cmd;
    qos_class_t qos; int rel;
    double t_start, t_end;
} job_t;

static job_t jobs[MAXTH];
static int pool_ready = 0;

static double now(void){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9;}

static void *worker(void *arg) {
    job_t *j = arg;
    int rc = pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0);
    pthread_get_qos_class_np(pthread_self(), &j->qos, &j->rel);
    fprintf(stderr, "worker qos=0x%x rel=%d setrc=%d\n", (unsigned)j->qos, j->rel, rc);
    for (;;) {
        int c;
        while ((c = atomic_load_explicit(&j->cmd, memory_order_acquire)) == 0) ;
        if (c == 2) return NULL;
        j->t_start = now();
        memset(j->Xi, 0, 16);
        aesni_gcm_encrypt(j->in, j->out, j->len, j->key, j->ivec, j->Xi);
        j->t_end = now();
        atomic_store_explicit(&j->cmd, 0, memory_order_release);
    }
}

static void init_pool(void) {
    if (pool_ready) return;
    qos_class_t q; int r;
    pthread_get_qos_class_np(pthread_self(), &q, &r);
    fprintf(stderr, "main qos=0x%x rel=%d\n", (unsigned)q, r);
    pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0);
    for (int i = 0; i < MAXTH; i++) {
        memset(&jobs[i], 0, sizeof(jobs[i]));
        pthread_t th; pthread_attr_t attr; pthread_attr_init(&attr);
        pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
        pthread_create(&th, &attr, worker, &jobs[i]);
        pthread_attr_destroy(&attr);
    }
    pool_ready = 1;
}

static void inc_ctr(unsigned char ctr[16], size_t blocks) {
    unsigned c = ((unsigned)ctr[12]<<24)|((unsigned)ctr[13]<<16)|((unsigned)ctr[14]<<8)|ctr[15];
    c += (unsigned)blocks; ctr[12]=c>>24; ctr[13]=c>>16; ctr[14]=c>>8; ctr[15]=c;
}

static PyObject *bench(PyObject *self, PyObject *args) {
    Py_buffer pt; int threads;
    if (!PyArg_ParseTuple(args, "y*i", &pt, &threads)) return NULL;
    init_pool();
    if (threads > MAXTH) threads = MAXTH;
    unsigned char key[16]; memset(key, 1, 16);
    unsigned char nonce[12]; memset(nonce, 2, 12);
    AES_KEY ak; aesni_set_encrypt_key(key, 128, &ak);
    unsigned char *ct = malloc(pt.len);
    size_t blocks = pt.len/BLOCK, chunk=(blocks/threads)&~(size_t)7, off=0;
    double t0 = now();
    for (int i=0;i<threads;i++){
        size_t nb=(i==threads-1)?(blocks-off/BLOCK):chunk;
        jobs[i].in=(unsigned char*)pt.buf+off; jobs[i].out=ct+off; jobs[i].len=nb*BLOCK; jobs[i].key=&ak;
        memset(jobs[i].ivec,0,16); memcpy(jobs[i].ivec,nonce,12); jobs[i].ivec[15]=2;
        inc_ctr(jobs[i].ivec, off/BLOCK); off+=nb*BLOCK;
        atomic_store_explicit(&jobs[i].cmd, 1, memory_order_release);
    }
    for (int i=0;i<threads;i++) while (atomic_load_explicit(&jobs[i].cmd, memory_order_acquire)!=0);
    double t1 = now();
    fprintf(stderr, "wall %.4f\n", t1-t0);
    for (int i=0;i<threads;i++) fprintf(stderr, "  worker %d: %.4f\n", i, jobs[i].t_end-jobs[i].t_start);
    free(ct);
    PyBuffer_Release(&pt);
    Py_RETURN_NONE;
}

static PyMethodDef methods[] = {{"bench", bench, METH_VARARGS, ""}, {NULL,NULL,0,NULL}};
static struct PyModuleDef module = {PyModuleDef_HEAD_INIT, "aesgcm_fast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_aesgcm_fast(void){return PyModule_Create(&module);}
