    EVP_CIPHER_CTX_free(ctx);
    printf("ct  = "); for(int i=0;i<32;i++) printf("%02x", ct[i]); printf("\n");
    printf("tag = "); for(int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");

    /* J0 = nonce || 0x00000001 ; E(K, J0) */
    unsigned char J0[16]; memcpy(J0, nonce, 12); J0[12]=0; J0[13]=0; J0[14]=0; J0[15]=1;
    unsigned char EKJ0[16]; aesni_encrypt(J0, EKJ0, &ak);
