       aad=0, ct bits = 256 = 0x100, so last two bytes 0x01 0x00. yes. */

    unsigned char buf[48]; memcpy(buf, ct, 32); memcpy(buf+32, lenblock, 16);

    /* try all reasonable H orderings and compare ghash output to expected S */
    unsigned char S_expected[16];
    const char *shex="e54168526697a3a361a69fd9bbc9bbd0";
    for(int i=0;i<16;i++){unsigned v; sscanf(shex+2*i,"%2x",&v); S_expected[i]=v;}
