       PCLMUL product then reduction with poly 0x87 reflected = constant below. */
    __m128i a = _mm_clmulepi64_si128(X, H, 0x00);
    __m128i b = _mm_clmulepi64_si128(X, H, 0x11);
    __m128i c = _mm_clmulepi64_si128(X, H, 0x10);
    __m128i d = _mm_clmulepi64_si128(X, H, 0x01);
    __m128i e = _mm_xor_si128(c, d);
    a = _mm_xor_si128(a, _mm_slli_si128(e, 8));
    b = _mm_xor_si128(b, _mm_srli_si128(e, 8));
