    __m128i poly = _mm_set_epi32(0x00000000, 0x00000087, 0, 0); /* not used directly */
    (void)poly;
    /* Gueron reduction for reflected form:
       X0 = a (low), X1 = b (high) */
    __m128i t = _mm_clmulepi64_si128(a, _mm_set_epi32(0,0,0,0x87), 0x00); /* low64(a) * 0x87 */
