    r.lo = ((uint64_t)p[8]<<56)|((uint64_t)p[9]<<48)|((uint64_t)p[10]<<40)|((uint64_t)p[11]<<32)|
           ((uint64_t)p[12]<<24)|((uint64_t)p[13]<<16)|((uint64_t)p[14]<<8)|p[15];
    return r;
}
static void store_be(unsigned char *p, u128b r){
    for(int i=0;i<8;i++) p[i] = r.hi >> (56-8*i);
    for(int i=0;i<8;i++) p[8+i] = r.lo >> (56-8*i);
