        Y = clmul_reduce(Y, Hv);
    }
    Y = bitrev128(Y);
    _mm_storeu_si128((__m128i*)out, Y);
}

int main(){
    unsigned char key[16]; memset(key,0x11,16);
    AES_KEY ak; aesni_set_encrypt_key(key,128,&ak);
    unsigned char H[16], zero[16]={0}; aesni_encrypt(zero,H,&ak);
    unsigned char nonce[12]; memset(nonce,0x22,12);
