    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    unsigned char aad[20]; for(int i=0;i<20;i++) aad[i]=0xA0+i;
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 20);
