    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);

    unsigned char buf[80]; memset(buf,0,80);
    memcpy(buf, aad, 20); memcpy(buf+32, ct, 32);
    buf[64+7]=0xA0; buf[78]=0x01;
    unsigned char S[16]; ghash_clmul(buf, 80, H, S);
    unsigned char J0[16]; memcpy(J0, nonce, 12); J0[15]=1;
    unsigned char EKJ0[16]; aesni_encrypt(J0, EKJ0, &ak);
    unsigned char mytag[16]; for(int i=0;i<16;i++) mytag[i]=S[i]^EKJ0[i];
    p16("computed", mytag); p16("expected", tag);
    printf("match %d\n", memcmp(mytag, tag, 16)==0);
    return 0;
}
