/* schoolbook in GCM reflected convention: leftmost bit (bit 127) is x^0.
   Multiplication by x is a right shift; reduction constant 0xE1 at the top. */
static void school_refl(uint64_t xh, uint64_t xl, uint64_t hh, uint64_t hl, uint64_t *oh, uint64_t *ol){
    uint64_t zh=0, zl=0, vh=hh, vl=hl;
    for(int i=0;i<128;i++){
        int bit = i<64 ? (xh>>(63-i))&1 : (xl>>(127-i))&1;
        if(bit){ zh^=vh; zl^=vl; }
        int lsb = vl & 1;
        vl = (vl>>1) | (vh<<63);
        vh >>= 1;
        if(lsb) vh ^= 0xE100000000000000ULL;
    }
    *oh=zh; *ol=zl;
}

/* candidate CLMUL reduction (reflected). We XOR data in reflected byte order and
   compare. Here we just test the multiply of two raw 128-bit values. */
static void clmul_cand(uint64_t xh, uint64_t xl, uint64_t hh, uint64_t hl, uint64_t *oh, uint64_t *ol){
    __m128i X = _mm_set_epi64x(xh, xl);
    __m128i Hv = _mm_set_epi64x(hh, hl);
    __m128i lo = _mm_clmulepi64_si128(X, Hv, 0x00);
    __m128i hi = _mm_clmulepi64_si128(X, Hv, 0x11);
    __m128i mid = _mm_xor_si128(_mm_clmulepi64_si128(X, Hv, 0x10), _mm_clmulepi64_si128(X, Hv, 0x01));
    lo = _mm_xor_si128(lo, _mm_slli_si128(mid, 8));
    hi = _mm_xor_si128(hi, _mm_srli_si128(mid, 8));
    /* try the published reflected reduction exactly */
    __m128i t0 = lo, t1 = hi;
    __m128i s = _mm_xor_si128(_mm_xor_si128(_mm_slli_epi64(t0, 63), _mm_slli_epi64(t0, 62)), _mm_slli_epi64(t0, 57));
    t0 = _mm_xor_si128(t0, _mm_slli_si128(s, 8));
    __m128i r = _mm_xor_si128(_mm_xor_si128(_mm_srli_epi64(t0, 1), _mm_srli_epi64(t0, 2)), _mm_srli_epi64(t0, 7));
    t0 = _mm_xor_si128(t0, _mm_srli_si128(r, 8));
    t1 = _mm_xor_si128(t1, _mm_slli_si128(r, 8));
    t1 = _mm_xor_si128(t1, t0);
    *oh = _mm_extract_epi64(t1, 1);
    *ol = _mm_extract_epi64(t1, 0);
}

int main(){
