    uint64_t hh=0x0f1e2d3c4b5a6978ULL, hl=0x8877665544332211ULL;
    uint64_t sh, sl, ch, cl;
    school_refl(xh, xl, hh, hl, &sh, &sl);
    clmul_cand(xh, xl, hh, hl, &ch, &cl);
    printf("school %016llx %016llx\n", sh, sl);
    printf("clmul  %016llx %016llx\n", ch, cl);
