#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <immintrin.h>

/* Reduce a 256-bit product (p3:p2:p1:p0), where bit 0 of p0 is x^0 (natural),
   one bit at a time, and record. Then compare to a CLMUL formulation. */
static void reduce_ref(uint64_t p3, uint64_t p2, uint64_t p1, uint64_t p0, uint64_t *oh, uint64_t *ol){
    /* bits 128..255 reduce via x^128 = x^7+x^2+x+1, i.e. xor 0x87 shifted */
    for (int k = 0; k < 64; k++) if ((p2 >> k) & 1) {
        /* bit (128+k) -> xor poly at bit k */
        uint64_t v = 0x87ULL << k;
        p0 ^= v;
        if (k > 56) p1 ^= (0x87ULL >> (64 - k)); /* spill */
    }
    for (int k = 0; k < 64; k++) if ((p3 >> k) & 1) {
        /* bit (192+k) -> xor poly at bit (64+k) */
        if (k <= 56) { p1 ^= 0x87ULL << k; if (k > 0) {/*spill into p2 but p2 already consumed*/ } }
        else { p1 ^= 0x87ULL << k; /* spills above bit 127: bit (64+k) for k>63 impossible within p1.
               0x87<<k with k<=63 fits in bits 0..69, so spill bits 64..69 go to position 128.. = p2 region
               which itself reduces. Handle explicitly: */ }
        int spill_shift = k - 57; /* bits of (0x87<<k) above bit 63: for k>=57 */
        if (k >= 57) {
            uint64_t spill = 0x87ULL >> (64 - k); /* the part above bit 63, at position (128 + (k-64))? no.
               (0x87 << k) bit position b (0..69). Bits >= 64 land at result bit (64+k) mapped... let's redo. */
            (void)spill; (void)spill_shift;
        }
    }
    (void)p3; *oh = p1; *ol = p0;
}

/* Direct: build full 256-bit product then reduce with a simple loop over the high 128 bits. */
static void prod(uint64_t ah, uint64_t al, uint64_t bh, uint64_t bl, uint64_t *p3, uint64_t *p2, uint64_t *p1, uint64_t *p0){
    __m128i z0 = _mm_clmulepi64_si128(_mm_cvtsi64_si128(al), _mm_cvtsi64_si128(bl), 0x00);
    __m128i z3 = _mm_clmulepi64_si128(_mm_cvtsi64_si128(ah), _mm_cvtsi64_si128(bh), 0x00);
    __m128i z1 = _mm_clmulepi64_si128(_mm_cvtsi64_si128(al), _mm_cvtsi64_si128(bh), 0x00);
    __m128i z2 = _mm_clmulepi64_si128(_mm_cvtsi64_si128(ah), _mm_cvtsi64_si128(bl), 0x00);
    uint64_t z0l=_mm_cvtsi128_si64(z0), z0h=_mm_extract_epi64(z0,1);
    uint64_t z3l=_mm_cvtsi128_si64(z3), z3h=_mm_extract_epi64(z3,1);
    uint64_t z1l=_mm_cvtsi128_si64(z1), z1h=_mm_extract_epi64(z1,1);
    uint64_t z2l=_mm_cvtsi128_si64(z2), z2h=_mm_extract_epi64(z2,1);
    *p0 = z0l;
    *p1 = z0h ^ z1l ^ z2l;
    *p2 = z3l ^ z1h ^ z2h;
    *p3 = z3h;
}

static void reduce(uint64_t p3, uint64_t p2, uint64_t p1, uint64_t p0, uint64_t *oh, uint64_t *ol){
    /* fold high 128 bits. For bit position 128+k (k=0..127), xor 0x87 at bit k. */
    uint64_t r0 = p0, r1 = p1;
    /* k = 0..63 from p2 */
    r0 ^= p2;                          /* bit k */
    r0 ^= p2 << 1;  r1 ^= p2 >> 63;    /* bit k+1 */
    r0 ^= p2 << 2;  r1 ^= p2 >> 62;    /* bit k+2 */
    r0 ^= p2 << 7;  r1 ^= p2 >> 57;    /* bit k+7 */
    /* k = 64..127 from p3: bit (128 + 64 + j) = bit (192+j) reduces to bit (64+j) */
    uint64_t spill = 0;                /* bits that land at >= 128, to be folded again */
    r1 ^= p3;                          /* bit 64+j */
    r1 ^= p3 << 1; spill ^= p3 >> 63;  /* bit 65+j, spill bit 128 */
    r1 ^= p3 << 2; spill ^= p3 >> 62;  /* bit 66+j */
    r1 ^= p3 << 7; spill ^= p3 >> 57;  /* bit 71+j, spill bits 128..134 */
    /* fold spill (bits 128 + m, m small) */
    r0 ^= spill;
    r0 ^= spill << 1;
    r0 ^= spill << 2;
    r0 ^= spill << 7;
    *ol = r0; *oh = r1;
}

static void school(uint64_t ah, uint64_t al, uint64_t bh, uint64_t bl, uint64_t *oh, uint64_t *ol){
    uint64_t zh=0, zl=0, vh=bh, vl=bl;
    for (int i=0;i<128;i++){
        int bit = i<64 ? (al>>i)&1 : (ah>>(i-64))&1;
        if (bit){ zh^=vh; zl^=vl; }
        int msb = (vh>>63)&1;
        vh = (vh<<1)|(vl>>63); vl <<= 1;
        if (msb) vl ^= 0x87;
    }
    *oh=zh; *ol=zl;
}

int main(){
    uint64_t ah=0x0123456789abcdefULL, al=0xfedcba9876543210ULL;
    uint64_t bh=0x0f1e2d3c4b5a6978ULL, bl=0x8877665544332211ULL;
    uint64_t p3,p2,p1,p0; prod(ah,al,bh,bl,&p3,&p2,&p1,&p0);
    printf("product %016llx %016llx %016llx %016llx\n", p3,p2,p1,p0);
    uint64_t rh, rl; reduce(p3,p2,p1,p0,&rh,&rl);
    uint64_t sh, sl; school(ah,al,bh,bl,&sh,&sl);
    printf("reduce  %016llx %016llx\n", rh, rl);
    printf("school  %016llx %016llx\n", sh, sl);
    printf("match %d\n", rh==sh && rl==sl);
    return 0;
}
