static void p16(const char *l, const unsigned char *p){printf("%-14s ", l); for(int i=0;i<16;i++) printf("%02x", p[i]); printf("\n");}

static inline uint64_t brev64(uint64_t x){
    x=((x&0x5555555555555555ULL)<<1)|((x&0xAAAAAAAAAAAAAAAAULL)>>1);
    x=((x&0x3333333333333333ULL)<<2)|((x&0xCCCCCCCCCCCCCCCCULL)>>2);
    x=((x&0x0F0F0F0F0F0F0F0FULL)<<4)|((x&0xF0F0F0F0F0F0F0F0ULL)>>4);
    x=((x&0x00FF00FF00FF00FFULL)<<8)|((x&0xFF00FF00FF00FF00ULL)>>8);
    x=((x&0x0000FFFF0000FFFFULL)<<16)|((x&0xFFFF0000FFFF0000ULL)>>16);
    return (x<<32)|(x>>32);
}
static void be_load(const unsigned char *p, uint64_t *h, uint64_t *l){
    *h=((uint64_t)p[0]<<56)|((uint64_t)p[1]<<48)|((uint64_t)p[2]<<40)|((uint64_t)p[3]<<32)|((uint64_t)p[4]<<24)|((uint64_t)p[5]<<16)|((uint64_t)p[6]<<8)|p[7];
    *l=((uint64_t)p[8]<<56)|((uint64_t)p[9]<<48)|((uint64_t)p[10]<<40)|((uint64_t)p[11]<<32)|((uint64_t)p[12]<<24)|((uint64_t)p[13]<<16)|((uint64_t)p[14]<<8)|p[15];
}
/* GCM block -> natural (bit0 = x^0): bit-reverse the whole 128 bits. */
static void to_natural(const unsigned char *p, uint64_t *nh, uint64_t *nl){
    uint64_t h, l; be_load(p, &h, &l);
    *nl = brev64(h);   /* GCM high bits (x^0..x^63) -> natural low bits */
    *nh = brev64(l);
}
static void from_natural(uint64_t nh, uint64_t nl, unsigned char *p){
    uint64_t h = brev64(nl), l = brev64(nh);
    for(int i=0;i<8;i++) p[i]=h>>(56-8*i);
    for(int i=0;i<8;i++) p[8+i]=l>>(56-8*i);
}

static void mul128(uint64_t ah, uint64_t al, uint64_t bh, uint64_t bl, uint64_t *oh, uint64_t *ol){
    __m128i z0=_mm_clmulepi64_si128(_mm_cvtsi64_si128(al),_mm_cvtsi64_si128(bl),0x00);
    __m128i z3=_mm_clmulepi64_si128(_mm_cvtsi64_si128(ah),_mm_cvtsi64_si128(bh),0x00);
    __m128i z1=_mm_clmulepi64_si128(_mm_cvtsi64_si128(al),_mm_cvtsi64_si128(bh),0x00);
    __m128i z2=_mm_clmulepi64_si128(_mm_cvtsi64_si128(ah),_mm_cvtsi64_si128(bl),0x00);
    uint64_t z0l=_mm_cvtsi128_si64(z0), z0h=_mm_extract_epi64(z0,1);
    uint64_t z3l=_mm_cvtsi128_si64(z3), z3h=_mm_extract_epi64(z3,1);
    uint64_t z1l=_mm_cvtsi128_si64(z1), z1h=_mm_extract_epi64(z1,1);
    uint64_t z2l=_mm_cvtsi128_si64(z2), z2h=_mm_extract_epi64(z2,1);
    uint64_t p0=z0l, p1=z0h^z1l^z2l, p2=z3l^z1h^z2h, p3=z3h;
    uint64_t r0=p0^p2, r1=p1^(p2>>63);
    r0^=p2<<1; r1^=p2>>63; r0^=p2<<2; r1^=p2>>62; r0^=p2<<7; r1^=p2>>57;
    uint64_t spill=0; r1^=p3; r1^=p3<<1; spill^=p3>>63; r1^=p3<<2; spill^=p3>>62; r1^=p3<<7; spill^=p3>>57;
    r0^=spill; r0^=spill<<1; r0^=spill<<2; r0^=spill<<7;
