static void ghash(const unsigned char *data, size_t len, const unsigned char *H, unsigned char *out){
    uint64_t Hh, Hl; to_natural(H, &Hh, &Hl);
    uint64_t yh=0, yl=0;
    for(size_t i=0;i<len;i+=16){
        uint64_t bh, bl; to_natural(data+i, &bh, &bl);
