        double best=1e9;
        for(int rep=0;rep<4;rep++){
            pthread_t t[8]; size_t rs[8][2]; size_t chunk=N/th; double t0=now();
            for(int i=0;i<th;i++){ rs[i][0]=i*chunk; rs[i][1]=(i==th-1)?N:(i+1)*chunk;
